'use strict';
const $=s=>document.querySelector(s), view=$('#view'), nav=$('#nav'), title=$('#page-title');
const state={overview:{},tokens:[],alerts:[],watchlist:[],wallets:[],autoWallets:[],creators:[],creatorFundingClusters:[],walletIntel:[],walletClusters:[],experts:{},walletGraph:null,walletReputation:null,walletSignalBacktest:null,dataQuality:null,launches:[],backtest:null,historical:null,learning:null,selected:null,page:'overview',sort:'score',search:'',loadErrors:[]};
const labels={overview:'Accueil',scanner:'Sélection',opportunities:'Opportunités',watchlist:'Favoris',analysis:'Détails du token',smart:'Wallets suivis',security:'Sécurité',social:'Liens du token',alerts:'Alertes',settings:'Réglages',creators:'Créateurs',backtest:'Résultats',smartIntel:'Activité des wallets',walletGraph:'Graphe wallets',quality:'Qualité des données',more:'Plus',launches:'Nouveaux lancements',experts:'Experts & portefeuilles'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Date(v).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'}):'—';
const usd=v=>Number(v)?new Intl.NumberFormat('fr-FR',{style:'currency',currency:'USD',maximumFractionDigits:Number(v)<1?6:0}).format(Number(v)):'—';
const short=v=>v?String(v).slice(0,5)+'…'+String(v).slice(-5):'—';
const pill=(s,c='neutral')=>'<span class="pill '+c+'">'+esc(s)+'</span>';
async function api(url,opts={}){const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});if(r.status===401){location.replace('/login');throw Error('Session expirée');}const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Erreur '+r.status);return d;}
function tokenTable(list){if(!list.length)return '<div class="empty-inline">Aucun token détecté pour le moment.</div>';return '<div class="table-wrap"><table><thead><tr><th>Token</th><th>Score</th><th>Couverture</th><th>Liquidité</th><th>Vol. 1h</th><th>Risque</th><th></th></tr></thead><tbody>'+list.map(t=>{const a=t.analysis||{},risk=a.hardBlocked?pill('Bloqué','bad'):a.risk==='unknown'?pill('Inconnu'):pill(a.risk==='high'?'Élevé':a.risk==='medium'?'À surveiller':'Observations',a.risk==='high'?'bad':a.risk==='medium'?'warn':'good');return '<tr><td><b>'+esc(t.name||'Nouveau token')+'</b><small class="subtle">$'+esc(t.symbol||'—')+' · '+esc(short(t.mint))+'</small></td><td><b class="score '+(Number(a.score)>=75?'good':Number(a.score)>=55?'warn':'neutral')+'">'+(a.score??'—')+'</b></td><td>'+pill(a.readinessLabel||'État inconnu',a.readiness==='complete'?'good':a.readiness==='partial'?'warn':'neutral')+'<small class="subtle">'+(a.coverage??0)+'% des facteurs disponibles</small></td><td>'+usd(t.liquidityUsd)+'</td><td>'+usd(t.volume?.h1)+'</td><td>'+risk+'</td><td><button class="mini-btn" data-token="'+esc(t.mint)+'">Détails</button> <button class="mini-btn" data-watch="'+esc(t.mint)+'">'+(state.watchlist.includes(t.mint)?'★':'☆')+'</button></td></tr>';}).join('')+'</tbody></table></div>';}
function filters(){return '<div class="filters"><input id="search-token" placeholder="Rechercher un token…" value="'+esc(state.search)+'"><select id="sort-token"><option value="score" '+(state.sort==='score'?'selected':'')+'>Meilleur score</option><option value="newest" '+(state.sort==='newest'?'selected':'')+'>Plus récent</option><option value="liquidity" '+(state.sort==='liquidity'?'selected':'')+'>Liquidité</option><option value="volume" '+(state.sort==='volume'?'selected':'')+'>Volume 24h</option><option value="momentum" '+(state.sort==='momentum'?'selected':'')+'>Pression acheteuse</option></select></div>';}
function sourceCards(){const names={dexscreener:'DexScreener',solanaRpc:'Solana RPC public',pumpPortal:'PumpPortal · créations live',geckoTerminal:'GeckoTerminal · nouveaux pools',redditRss:'Reddit · signaux sociaux',bluesky:'Bluesky · recherche publique',nostr:'Nostr · relais public',telegramSocial:'Telegram · canaux publics',telegram:'Telegram · alertes du bot'};return '<div class="source-grid">'+Object.entries(state.overview.sources||{}).map(([k,s])=>'<article class="panel source-card"><b>'+esc(names[k]||k)+'</b> '+pill(s.connected?'Connecté':s.configured?'Configuré':'Clé requise',s.connected?'good':s.configured?'warn':'neutral')+'<p>'+esc(s.mode||'')+'</p><small>'+esc(s.error||s.lastError||s.lastSuccess||'En attente de configuration')+'</small></article>').join('')+'</div>';}
function selectionPools(){
 const tokens=state.tokens.filter(t=>!t.analysis?.hardBlocked&&t.analysis?.risk!=='high'&&t.analysis?.risk!=='unknown'&&Boolean(t.pairAddress||t.geckoPoolAddress));
 const valid=(t,keys)=>keys.every(k=>typeof t.analysis?.factors?.[k]==='number'&&Number.isFinite(t.analysis.factors[k]));
 const quality=t=>Number(t.analysis?.coverage||0)>=80&&Number(t.analysis?.score||0)>=68&&Number(t.liquidityUsd||0)>=10000&&Number(t.volume?.h1||0)>=1000&&Number(t.txns?.h1?.buys||0)+Number(t.txns?.h1?.sells||0)>=10&&t.analysis?.securityComprehensive===true&&t.analysis?.risk==='observations_only'&&valid(t,['activity','momentum','market','liquidityQuality','security']);
 const watch=t=>Number(t.analysis?.coverage||0)>=65&&Number(t.analysis?.score||0)>=58&&Number(t.liquidityUsd||0)>=5000&&Number(t.volume?.h1||0)>0&&valid(t,['market','security']);
 const sort=(a,b)=>Number(b.analysis?.score||0)-Number(a.analysis?.score||0)||Number(b.liquidityUsd||0)-Number(a.liquidityUsd||0);
 const best=tokens.filter(quality).sort(sort).slice(0,5),selected=new Set(best.map(t=>t.mint));
 const observe=tokens.filter(t=>!selected.has(t.mint)&&watch(t)).sort(sort).slice(0,5);
 return {best,observe,eligible:tokens.length};
}
function candidateCards(items,emptyText){
 const closeTag=name=>'<'+ '/'+name+'>';
 if(!items.length)return '<div class="empty-inline">'+esc(emptyText)+closeTag('div');
 return '<div class="candidate-list">'+items.map((t,i)=>{const a=t.analysis||{},buy=Number(t.txns?.h1?.buys||0),sell=Number(t.txns?.h1?.sells||0),ratio=buy+sell?Math.round(buy/(buy+sell)*100):null;return '<article class="panel candidate-card"><div class="candidate-rank">'+(i+1)+closeTag('div')+'<div class="candidate-main"><div class="candidate-title"><b>'+esc(t.name||'Token sans nom')+closeTag('b')+'<span>$'+esc(t.symbol||'—')+closeTag('span')+closeTag('div')+'<div class="candidate-meta">'+pill('Analyse '+a.coverage+'%','good')+' '+pill(a.risk==='medium'?'Risque moyen':a.risk==='partial'?'Preuves partielles':a.risk==='observations_only'?'Sécurité vérifiée':'Sécurité inconnue',a.risk==='observations_only'?'good':'warn')+closeTag('div')+'<div class="candidate-metrics"><span>Liquidité <b>'+usd(t.liquidityUsd)+closeTag('b')+closeTag('span')+'<span>Volume 1h <b>'+usd(t.volume?.h1)+closeTag('b')+closeTag('span')+'<span>Acheteurs <b>'+(ratio===null?'—':ratio+'%')+closeTag('b')+closeTag('span')+closeTag('div')+closeTag('div')+'<div class="candidate-score"><strong>'+a.score+closeTag('strong')+'<small>/100</small><button class="mini-btn" data-token="'+esc(t.mint)+'">Détails</button><button class="mini-btn" data-watch="'+esc(t.mint)+'">'+(state.watchlist.includes(t.mint)?'★':'☆')+closeTag('button')+closeTag('div')+closeTag('article');}).join('')+closeTag('div');
}
function renderOverview(){
 const p=selectionPools(),stats=[['Sélectionnés',p.best.length],['À surveiller',p.observe.length],['Favoris',state.watchlist.length]];
 view.innerHTML='<div class="welcome"><div><p class="eyebrow">MEME RADAR · SOLANA</p><h2>Une sélection courte. Des données solides.</h2><p>Seuls les tokens avec un marché actif, une liquidité suffisante et une analyse exploitable remontent ici.</p><div class="welcome-meta">'+pill(state.overview.scannerRunning?'Surveillance active':'Surveillance à vérifier',state.overview.scannerRunning?'good':'warn')+' <small>Mis à jour : '+date(state.overview.lastScanAt)+'</small>'+closeTag('div')+'<div class="welcome-actions"><button class="primary" data-go="scanner">Voir la sélection</button><button class="secondary" data-go="watchlist">Mes favoris</button>'+closeTag('div')+closeTag('div')+'<div class="orb">◎</div>'+closeTag('div')+'<div class="stat-grid simple-stats">'+stats.map(x=>'<article class="panel stat"><span>'+x[0]+'</span><strong>'+x[1]+'</strong>'+closeTag('article')).join('')+closeTag('div')+'<div class="section-heading"><div><h2>Les meilleurs candidats</h2><p class="muted">Maximum 5. Aucun token n’est ajouté pour remplir la liste.</p>'+closeTag('div')+closeTag('div')+candidateCards(p.best,'Aucun token ne passe actuellement tous les critères. C’est préférable à une fausse recommandation.')+'<p class="footnote">Sur '+p.eligible+' tokens avec un pool actif, '+p.best.length+' passent les critères stricts. Aucun score n’est garanti et aucun achat automatique n’est effectué.</p>';
}
function renderScanner(){
 const p=selectionPools();
 view.innerHTML='<div class="section-heading"><div><p class="eyebrow">FILTRE AUTOMATIQUE</p><h2>Sélection du Radar</h2><p class="muted">5 meilleurs maximum, puis 5 en observation. Les tokens mal documentés ou trop risqués sont écartés.</p>'+closeTag('div')+'<button class="primary" id="refresh-tokens">Actualiser</button>'+closeTag('div')+'<div class="selection-explainer"><b>Critères de sélection</b><span>Analyse ≥ 80 % · Score ≥ 68 · Liquidité ≥ 10 000 $ · Volume 1h ≥ 1 000 $ · Activité confirmée · Sécurité vérifiée</span>'+closeTag('div')+'<div class="section-heading compact-heading"><div><h3>Meilleurs candidats</h3><p class="muted">Ceux qui passent tous les critères stricts.</p>'+closeTag('div')+'<span class="count-pill">'+p.best.length+'/5</span>'+closeTag('div')+candidateCards(p.best,'Aucun candidat assez solide pour le moment. Le Radar préfère ne rien proposer plutôt que de sélectionner un token sur des données insuffisantes.')+'<div class="section-heading compact-heading"><div><h3>À surveiller</h3><p class="muted">Potentiels intéressants, mais critères stricts incomplets.</p>'+closeTag('div')+'<span class="count-pill">'+p.observe.length+'/5</span>'+closeTag('div')+candidateCards(p.observe,'Aucun token supplémentaire à surveiller.')+'<p class="footnote">Les autres tokens restent hors de la sélection : pool absent, couverture insuffisante, liquidité/activité trop faibles ou risque élevé. Les pré-marchés à 5 % ne sont pas présentés comme des opportunités.</p>';
}
function refreshTable(){if(state.page==='scanner')renderScanner();}
function renderDetail(){const t=state.selected;if(!t){view.innerHTML='<div class="empty-panel panel"><h2>Sélectionne un token</h2><p>Ouvre les détails depuis le scanner.</p></div>';return;}const a=t.analysis||{},s=t.security?.data||{},f=a.factors||{};const factorNames={activity:'Activité récente',momentum:'Pression acheteuse & accélération',market:'Marché',liquidityQuality:'Qualité de liquidité',earlyBuyerSignal:'Acheteurs précoces récurrents',security:'Sécurité',timing:'Ancienneté',tradeQuality:'Qualité des transactions observées',social:'Signal social public'};view.innerHTML='<div class="section-heading"><div><p class="eyebrow">TOKEN INTELLIGENCE</p><h2>'+esc(t.name||'Token')+' · $'+esc(t.symbol||'—')+'</h2><p class="mono muted">'+esc(t.mint)+'</p></div></div><div class="detail-grid"><article class="panel detail-score"><span class="eyebrow">SCORE</span><strong class="score huge">'+(a.score??'—')+'<small>/100</small></strong><p>'+((a.coverage??0)+'% des facteurs calculables')+'</p>'+pill(a.readinessLabel||'État inconnu',a.readiness==='complete'?'good':a.readiness==='partial'?'warn':'neutral')+'<p class="footnote">'+esc(a.readinessReason||'État de l’analyse non renseigné.')+'</p>'+(a.missingFactorReasons?.length?'<div class="missing-data"><b>Pourquoi la couverture est limitée</b>'+a.missingFactorReasons.map(x=>'<p class="factor-row">'+esc(x.label)+' : '+esc(x.reason)+'</p>').join('')+'</div>':'')+(a.evidenceGaps?.length?a.evidenceGaps.map(x=>'<p class="footnote">'+esc(x.reason)+'</p>').join(''):'')+pill('Confiance '+(a.confidence||'inconnue'))+'</article><article class="panel detail-card"><h3>Marché</h3><div class="metric-list">'+[['Prix',usd(t.priceUsd)],['Liquidité',usd(t.liquidityUsd)],['FDV',usd(t.fdv)],['Volume 1h',usd(t.volume?.h1)],['Volume 24h',usd(t.volume?.h24)],['Âge',Number.isFinite(Number(t.launchAgeHours))?Number(t.launchAgeHours).toFixed(1)+' h':t.ageHours==null?'—':t.ageHours.toFixed(1)+' h']].map(x=>'<span>'+x[0]+' <b>'+x[1]+'</b></span>').join('')+'</div></article><article class="panel detail-card"><h3>Facteurs disponibles</h3>'+Object.entries(f).map(([k,v])=>'<p class="factor-row">'+esc(factorNames[k]||k)+' <b>'+Math.round(v)+'/100</b></p>').join('')+'</article></div><article class="panel detail-card"><h3>Intelligence complémentaire</h3><p>Score de base : <b>'+(a.baseScore??'—')+'/100</b> · Ajustement limité des signaux complémentaires : <b>'+(a.candidateIntel?.adjustment??0)+'</b></p>'+((a.candidateIntel?.reasons||[]).length?a.candidateIntel.reasons.map(x=>'<p class="factor-row">'+esc(x)+'</p>').join(''):'<p class="muted">Pas encore assez de données transactionnelles ou sociales pour enrichir ce score.</p>')+'<p class="footnote">Les transactions GeckoTerminal sont un échantillon public limité. Les mentions sociales viennent des flux Reddit, Bluesky et Nostr publics. Ces indices ne prouvent ni coordination, ni intérêt réel, ni hausse future.</p></article><div class="two-col"><article class="panel detail-card"><h3>Sécurité '+esc(t.security?.provider||'')+'</h3>'+(t.security?.checkedAt?'<p>Mint authority : <b>'+(s.mintAuthorityActive?'Active':'Révoquée / inconnue')+'</b></p><p>Freeze authority : <b>'+(s.freezeAuthorityActive===true?'Active':s.freezeAuthorityActive===false?'Inactive':'Inconnue')+'</b></p><p>Mint initialisé : <b>'+(s.isInitialized===true?'Oui':'Non / inconnu')+'</b></p><p>Programme : <b>'+(s.isToken2022?'Token-2022':'SPL Token standard / inconnu')+'</b></p><p>Top 10 wallets (agrégés) : <b>'+(s.top10HolderPercent==null?'Inconnu':s.top10HolderPercent+'%')+'</b></p><p>Top 1 wallet : <b>'+(s.top1OwnerPercent==null?'Inconnu':s.top1OwnerPercent+'%')+'</b> · Top 5 : <b>'+(s.top5OwnerPercent==null?'Inconnu':s.top5OwnerPercent+'%')+'</b></p><p>Détenteurs distincts identifiés dans l’échantillon : <b>'+(s.uniqueOwnerCount||'—')+'</b></p><p>Concentration top 20 : <b>'+(s.top20HolderPercent==null?'Inconnue':s.top20HolderPercent+'%')+'</b> · Gini top 20 : <b>'+(s.holderGiniTop20==null?'Inconnu':s.holderGiniTop20.toFixed(3))+'</b></p><p>HHI top 20 : <b>'+(s.holderHhiTop20==null?'Inconnu':s.holderHhiTop20.toFixed(2))+'</b> · nombre effectif de détenteurs observés : <b>'+(s.effectiveOwnersTop20==null?'Inconnu':s.effectiveOwnersTop20)+'</b></p><p>Échantillon RPC : <b>'+(s.holderSampleAccounts||0)+' comptes / '+(s.holderSampleOwners||0)+' propriétaires identifiés</b> · part de supply dans les 20 comptes : <b>'+(s.holderSampleCoveragePct==null?'Inconnue':s.holderSampleCoveragePct+'%')+'</b></p><p>Concentration des 10 comptes : <b>'+(s.top10AccountPercent==null?'Inconnu':s.top10AccountPercent+'%')+'</b></p><p class="footnote">Gini et HHI sont calculés uniquement sur les 20 comptes les plus importants renvoyés par le RPC. Ce sont des indicateurs partiels, pas une cartographie complète des détenteurs ni une preuve de propriété commune.</p><p>Risque : '+pill(a.risk||'Inconnu',a.hardBlocked?'bad':'warn')+'</p>':'<p>Inconnu. Les contrôles RPC se déclenchent à l\'ouverture de la fiche token.</p>')+'<p class="footnote">Observations du RPC public, pas un audit ni une garantie.</p><h3>Deuxième avis indépendant · GL1TCH</h3>'+(t.externalSecurity?.status==='ok'?'<p>Verdict : <b>'+esc(t.externalSecurity.verdict||'Non fourni')+'</b></p><p>Score fournisseur : <b>'+(t.externalSecurity.score==null?'Non fourni':t.externalSecurity.score+'/100')+'</b> · Confiance : <b>'+esc(t.externalSecurity.confidence||'Non fournie')+'</b></p><p>'+esc(t.externalSecurity.bottomLine||'')+'</p>'+((t.externalSecurity.checks||[]).map(x=>'<p class="factor-row">'+esc(x.name)+' · <b>'+esc(x.status||x.severity||'Résultat disponible')+'</b><small>'+esc(x.details||'')+'</small></p>').join('')||'<p>Aucun détail de contrôle retourné.</p>')+'<p><a class="external-link" href="'+esc(t.externalSecurity.url||'https://gl1tchbased.xyz/scan')+'" target="_blank" rel="noopener">Ouvrir le rapport GL1TCH ↗</a></p>': '<p>'+(t.externalSecurity?.status==='rate_limited'?'Limite locale atteinte, réessaie dans une minute.':t.externalSecurity?.error?'Service indisponible : '+esc(t.externalSecurity.error):'Rapport pas encore disponible.')+'</p>')+'<p class="footnote">Source tierce gratuite sans clé API. Son score reste séparé de MEME RADAR et ne garantit pas la sécurité.</p><h3>Alertes de risque</h3>'+((a.flags||[]).length?a.flags.map(x=>'<p>'+pill(x.level==='critical'?'Critique':'À surveiller',x.level==='critical'?'bad':'warn')+' '+esc(x.message)+'</p>').join(''):'<p>Aucun drapeau détecté avec les données disponibles.</p>')+'<h3>Qualité du marché</h3><div class="metric-list">'+[['Volume / liquidité',t.metrics?.volumeToLiquidity??'—'],['FDV / liquidité',t.metrics?.fdvToLiquidity??'—'],['Variation liquidité',t.metrics?.liquidityChangePct==null?'—':t.metrics.liquidityChangePct+'%'],['Variation prix depuis mesure précédente',t.metrics?.priceChangeSincePrevious==null?'—':t.metrics.priceChangeSincePrevious+'%'],['Ratio achats/ventes',a.factors?.buySellRatio??'—'],['Part des achats',a.factors?.buyRatio==null?'—':a.factors.buyRatio+'%'],['Achats 5 min',a.marketSignals?.buyRatio5mPct==null?'—':a.marketSignals.buyRatio5mPct+'%'],['Volume 5 min / moyenne',a.marketSignals?.relativeVolume5m==null?'—':a.marketSignals.relativeVolume5m+'×'],['Variation prix 5 min',a.marketSignals?.priceChange5mPct==null?'—':a.marketSignals.priceChange5mPct+'%']].map(x=>'<span>'+x[0]+' <b>'+x[1]+'</b></span>').join('')+'</div></article><article class="panel detail-card"><h3>Wallets suivis</h3><p>'+(t.smartMoney?.hits||0)+' wallet(s) suivis repérés dans les transactions récentes.</p><p class="footnote">Ce n’est pas une liste automatique de traders rentables.</p>'+ '<h3>Flux de transactions · GeckoTerminal</h3>'+(t.tradeIntel?'<p>Transactions analysées : <b>'+t.tradeIntel.tradeCount+'</b> · Acheteurs uniques : <b>'+t.tradeIntel.uniqueBuyers+'</b> · Vendeurs uniques : <b>'+t.tradeIntel.uniqueSellers+'</b></p><p>Volume achats : <b>'+usd(t.tradeIntel.buyVolumeUsd)+'</b> · ventes : <b>'+usd(t.tradeIntel.sellVolumeUsd)+'</b></p><p>Part du volume des 5 principaux acheteurs : <b>'+(t.tradeIntel.top5BuyerSharePct==null?'—':t.tradeIntel.top5BuyerSharePct+'%')+'</b> · groupes d’achats dans le même bloc : <b>'+t.tradeIntel.sameBlockBuyerClusters+'</b> · rafales 5 secondes : <b>'+(t.tradeIntel.burstCandidates?.length||0)+'</b></p>'+((t.tradeIntel.bundleCandidates||[]).length?t.tradeIntel.bundleCandidates.map(x=>'<p class="factor-row">Bloc '+esc(x.block)+' · '+x.uniqueBuyers+' acheteurs · '+usd(x.buyVolumeUsd)+' · '+x.timeSpanMs+' ms · '+x.wallets.map(short).join(', ')+'</p>').join(''):'')+'<p>Fenêtre des 5 premières minutes : <b>'+(t.tradeIntel.earlyWindow?.complete?'couverte':'incomplète / indisponible')+'</b> · '+(t.tradeIntel.earlyWindow?.uniqueBuyers||0)+' acheteurs distincts</p>'+((t.tradeIntel.flags||[]).map(x=>'<p>'+pill('Indice à vérifier','warn')+' '+esc(x.message)+'</p>').join('')||'<p>Aucun indice de concentration ou de burst détecté dans les transactions récupérées.</p>')+((t.tradeIntel.topBuyers||[]).length?'<p class="footnote">Principaux acheteurs : '+t.tradeIntel.topBuyers.map(x=>esc(short(x.wallet))+' ('+x.buys+' achats)').join(' · ')+'</p>':''):'<p>'+(t.tradeIntelError?'Données indisponibles : '+esc(t.tradeIntelError):'Ouvre la fiche pour récupérer les transactions publiques du pool.')+'</p>')+'<p class="footnote">Jusqu’à 300 transactions des dernières 24h. Les achats groupés dans un même bloc sont des indices, pas une preuve de bundle, de sniper ou de coordination.</p><h3>Social Intelligence · Reddit + Bluesky + Nostr + Telegram public</h3><p>Mentions 1h : <b>'+(t.socialIntel?.mentions1h??0)+'</b> · 24h : <b>'+(t.socialIntel?.mentions24h??0)+'</b> · Auteurs distincts : <b>'+(t.socialIntel?.uniqueAuthors24h??0)+'</b> · Canaux Telegram : <b>'+(t.socialIntel?.uniqueChannels24h??0)+'</b> · Réseaux : <b>'+(t.socialIntel?.uniqueSources24h??0)+'</b></p><p>Sentiment lexical : <b>'+(t.socialIntel?.sentimentScore==null?'Données insuffisantes':t.socialIntel.sentimentScore+'/100')+'</b></p>'+((t.socialIntel?.posts||[]).length?(t.socialIntel.posts||[]).map(x=>'<p class="factor-row"><a class="external-link" href="'+esc(x.link)+'" target="_blank" rel="noopener">'+esc(x.title||x.text||'Publication publique')+'</a><small>'+esc(x.source)+' · '+date(x.publishedAt||x.createdAt)+'</small></p>').join(''):'<p>Aucune mention Reddit récente identifiée pour ce token.</p>')+'<p class="footnote">Sources : Reddit RSS, Bluesky public, relais Nostr NIP-50 et canaux Telegram publics liés aux métadonnées. Pas de recherche globale X/Telegram ni accès aux groupes privés. Les mentions ne prouvent ni intérêt réel ni hausse future.</p>'+'</article></div><p><a class="external-link" href="'+esc(t.dexUrl||t.geckoUrl||('https://dexscreener.com/solana/'+t.mint))+'" target="_blank" rel="noopener">Voir sur DexScreener ↗</a></p>'+(t.analysis?.hardBlocked?pill('Bloqué des opportunités','bad'):'');}
function renderWatchlist(){const list=state.watchlist.map(m=>state.tokens.find(t=>t.mint===m)).filter(Boolean);view.innerHTML='<div class="section-heading"><div><h2>Watchlist</h2><p class="muted">Tokens que tu as choisi de surveiller.</p></div></div>'+ (list.length?tokenTable(list):'<div class="panel empty-panel"><div class="empty-icon">☆</div><h2>Ta watchlist est vide</h2><p>Depuis le Live Scanner, appuie sur ☆ à côté d’un token pour l’ajouter ici.</p><button class="primary" data-go="scanner">Ouvrir le scanner</button></div>');}function renderSmart(){
 const automatic=state.autoWallets||[];
 const manualHtml=state.wallets.map(w=>'<article class="panel wallet-row"><div><b>'+esc(w.label||'Wallet')+'</b><p class="mono">'+esc(w.address)+'</p><small>'+esc(w.activity?.error||date(w.activity?.at))+'</small></div><button class="mini-btn" data-remove-wallet="'+esc(w.address)+'">Retirer</button></article>').join('');
 const automaticHtml=automatic.length?automatic.map(w=>'<article class="panel wallet-row"><div><b>'+esc(w.label||'Acheteur précoce observé')+'</b><p class="mono">'+esc(w.address)+'</p><small>Score de découverte : <b>'+((w.discoveryScore??'—')+'/100')+'</b> · '+(w.tokensObserved||w.sourceMints?.length||1)+' token(s) distinct(s) · '+(w.buysObserved||0)+' achats · volume '+usd(w.buyVolumeUsd)+'</small><small>'+esc((w.discoveryReasons||[]).join(' · ')||'Un seul échantillon observé')+'</small></div><span class="module-state">Suivi auto</span></article>').join(''):'<p class="muted">Aucun acheteur précoce repéré pour le moment. Le scanner ne retient que les acheteurs d’une fenêtre initiale de cinq minutes entièrement couverte.</p>';
 view.innerHTML='<div class="section-heading"><div><h2>Smart Money · Wallets suivis</h2><p class="muted">Ajoute tes propres adresses ou laisse le scanner repérer des acheteurs précoces à observer.</p></div></div><form id="wallet-form" class="panel inline-form"><input name="address" placeholder="Adresse wallet Solana" minlength="32" maxlength="44" required><input name="label" placeholder="Étiquette facultative" maxlength="60"><button class="primary">Ajouter</button></form><h3>Wallets ajoutés manuellement</h3>'+(manualHtml||'<p class="muted">Aucun wallet ajouté manuellement.</p>')+'<h3>Acheteurs précoces repérés automatiquement</h3>'+automaticHtml+'<p class="footnote">Le score de découverte combine récidive sur plusieurs tokens, nombre d’achats précoces et volume observé. Il classe les candidats, sans prédire leur rentabilité. Un seul échantillon ne suffit pas à établir une performance. Le suivi observe les mouvements publics et les variations de prix, pas le PnL réel.</p>';
}
function renderSecurity(){const a=state.tokens.filter(t=>t.security?.checkedAt||t.analysis?.hardBlocked);view.innerHTML='<h2>Sécurité des tokens</h2><p class="muted">Les contrôles incomplets sont indiqués comme inconnus, jamais comme sûrs.</p>'+tokenTable(a);}
function renderSocial(){
 const a=state.tokens.filter(t=>(t.socials||[]).length||(t.links||[]).length||(t.socialIntel?.mentions24h||0)>0);
 view.innerHTML='<h2>Social Radar & liens publics</h2><p class="muted">Mentions issues des flux RSS Reddit, de la recherche publique Bluesky, d&#39;un relais Nostr et des canaux Telegram publics liés aux métadonnées du token. Pas de recherche globale X ni Telegram.</p>'
 +(a.length?a.map(t=>'<article class="panel detail-card" style="margin:10px 0"><b>'+esc(t.name||'Token')+' · $'+esc(t.symbol||'—')+'</b><p>Mentions publiques : <b>'+(t.socialIntel?.mentions1h||0)+' sur 1h · '+(t.socialIntel?.mentions24h||0)+' sur 24h</b> · Auteurs : <b>'+(t.socialIntel?.uniqueAuthors24h||0)+'</b> · Canaux Telegram : <b>'+(t.socialIntel?.uniqueChannels24h||0)+'</b> · Réseaux : <b>'+(t.socialIntel?.uniqueSources24h||0)+'</b> · Sentiment lexical : <b>'+(t.socialIntel?.sentimentScore==null?'—':t.socialIntel.sentimentScore+'/100')+'</b></p>'+((t.socialIntel?.posts||[]).map(x=>'<p class="factor-row"><a class="external-link" href="'+esc(x.link)+'" target="_blank" rel="noopener">'+esc(x.title)+'</a><small>'+esc(x.source)+' · '+date(x.publishedAt)+'</small></p>').join('')||'')+'<button class="mini-btn" data-token="'+esc(t.mint)+'">Détails</button></article>').join(''):'<div class="empty-inline">Aucune mention détectée dans les sources publiques interrogées. Les flux peuvent être temporairement indisponibles.</div>')
 +'<p class="footnote">Le sentiment est un comptage lexical, pas une mesure fiable de popularité. Les canaux Telegram sont uniquement ceux référencés publiquement par les métadonnées des tokens; aucun groupe privé ni recherche globale n&#39;est consulté. Les collectes sont échantillonnées et mises en cache.</p>';
}
function renderCreators(){
 const clusters=state.creatorFundingClusters||[];
 const clusterHtml=clusters.length?'<div class="panel detail-card"><h3>Financeurs communs potentiels</h3>'+clusters.map(c=>'<p>'+c.creatorCount+' créateurs · '+c.tokenCount+' tokens · <span class="mono">'+esc(c.funder)+'</span> · '+c.totalFundingSol+' SOL observés</p>').join('')+'<small>Un financeur partagé peut être un exchange ou un service; ce n’est pas une preuve de coordination.</small></div>':'';
 const creatorsHtml=state.creators.length?state.creators.map(c=>'<article class="panel detail-card" style="margin:10px 0"><b>'+esc(c.assessment)+'</b> · '+c.tokenCount+' token(s)<p class="mono">'+esc(c.address)+'</p><p>Attribution : '+esc(c.attribution)+' · Rendement indicatif moyen à 1h : '+(c.average1hReturnPct==null?'—':c.average1hReturnPct+'%')+'</p><p>Sorties swap-like observées : <b>'+(c.creatorSaleCount||0)+'</b> · sorties totales de tokens : '+(c.creatorOutflowCount||0)+' · dernière sortie : '+date(c.lastCreatorSaleAt)+'</p>'+((c.creatorSwapEvidence||[]).map(e=>'<small>'+date(e.at)+' · '+Number(e.tokenAmount||0).toFixed(3)+' tokens · contre '+(e.quoteReceived?e.quoteReceived.amount+' '+e.quoteReceived.asset:'contrepartie inconnue')+'</small>').join('<br>'))+'</article>').join(''):'<div class="empty-inline">Aucun wallet créateur exploitable pour le moment.</div>';
 view.innerHTML='<h2>Analyse créateur</h2><p class="muted">Les wallets créateurs observés sont suivis via les événements Pump.fun. Le RPC public recherche aussi leur financeur direct dans l’historique accessible.</p>'+clusterHtml+creatorsHtml+'<p class="footnote">Le rendement est calculé à partir des prévisions du token, pas des gains du créateur. Les financeurs communs sont des indices à vérifier et ne prouvent pas une identité commune.</p>';
}
function renderBacktest(){
 const l=state.learning||{},r=l.successRate||{},s=l.summary||{},fp=l.falsePositiveAnalysis||{},cohorts=l.cohorts||{},oos=l.outOfSample||{},lc=l.launchCohorts||{universe:{},bySource:{}},h=r.evaluated||0,rate=r.ratePct==null?'En apprentissage':r.ratePct+'%';
 view.innerHTML='<div class="section-heading"><div><h2>Résultats du bot</h2><p class="muted">Les prévisions sont confrontées aux observations réelles du marché après leur émission.</p></div></div>'
 +'<div class="performance-hero panel"><span class="eyebrow">RÉUSSITE OBSERVÉE À 1 HEURE</span><strong>'+rate+'</strong><p>'+r.successful+' prévisions positives sur '+h+' évaluées</p><small>Une prévision est positive si le prix progresse d’au moins 15 % après environ une heure.</small></div>'
 +'<div class="stat-grid">'+[['Prévisions enregistrées',s.forecasts||0],['Prévisions évaluées',h],['Progression moyenne',r.averageReturnPct==null?'—':r.averageReturnPct+'%'],['Prévisions en baisse',r.lossRatePct==null?'—':r.lossRatePct+'%']].map(x=>'<article class="panel stat"><span>'+x[0]+'</span><strong>'+x[1]+'</strong></article>').join('')+'</div>'
 +'<div class="panel detail-card"><h3>Faux signaux et risques</h3><p>'+fp.strongSignals+' prévisions avec score ≥65 évaluées à 1h.</p><p>Parmi elles, '+fp.rugLikeOrSevereLoss+' ont subi une forte perte ou une forte baisse de liquidité ('+(fp.ratePct==null?'—':fp.ratePct+'%')+').</p><small>'+esc(fp.definition||'Indicateur de risque indicatif, pas une preuve de rug pull.')+'</small></div>'
 +'<div class="panel detail-card"><h3>Comment lire ces résultats ?</h3><p>Les observations neutres et négatives comptent comme non gagnantes.</p><p class="footnote">'+(h<30?'Échantillon encore limité : les taux sont provisoires.':'Échantillon de '+h+' observations. Plusieurs observations peuvent concerner le même token.')+'</p><p class="footnote">Ce ne sont pas des trades gagnants : aucun ordre n’est exécuté. Frais, slippage, impact de marché et possibilité réelle de vente ne sont pas simulés.</p></div>'
 +'<div class="section-heading spaced"><div><h2>Évolution selon la durée</h2><p class="muted">Résultats observés après chaque prévision.</p></div></div><div class="panel detail-card">'+Object.entries(s.horizons||{}).map(([k,v])=>'<p class="factor-row">'+({'15m':'15 minutes','1h':'1 heure','6h':'6 heures','24h':'24 heures','7d':'7 jours'}[k]||k)+' · '+v.resolved+' évaluées <b>'+(v.averageReturnPct==null?'En attente':v.averageReturnPct+'% moyen · '+v.winRatePct+'% positives')+'</b></p>').join('')+'</div>'
 +'<div class="two-col"><article class="panel detail-card"><h3>Résultats par source de découverte</h3>'+Object.entries(cohorts.bySource||{}).map(([name,v])=>'<p class="factor-row">'+esc(name)+' · '+v.resolved+' évaluées <b>'+(v.winRate1hPct==null?'—':v.winRate1hPct+'% positives')+' · '+(v.average1hPct==null?'—':v.average1hPct+'% moyen')+'</b></p>').join('')+'</article><article class="panel detail-card"><h3>Résultats selon l’âge du pool</h3>'+Object.entries(cohorts.byLaunchAge||{}).map(([name,v])=>'<p class="factor-row">'+esc(name)+' · '+v.resolved+' évaluées <b>'+(v.winRate1hPct==null?'—':v.winRate1hPct+'% positives')+' · '+(v.average1hPct==null?'—':v.average1hPct+'% moyen')+'</b></p>').join('')+'</article><article class="panel detail-card"><h3>Résultats selon la liquidité</h3><p class="footnote">Les pools peu profonds sont séparés, car leur prix est plus fragile.</p>'+Object.entries(cohorts.byLiquidity||{}).map(([name,v])=>'<p class="factor-row">'+esc(name.replaceAll('_',' '))+' · '+v.resolved+' évaluées <b>'+(v.winRate1hPct==null?'—':v.winRate1hPct+'% positives')+' · '+(v.average1hPct==null?'—':v.average1hPct+'% moyen')+' · '+(v.lossRate1hPct==null?'—':v.lossRate1hPct+'% pertes')+'</b></p>').join('')+'</article></div><article class="panel detail-card"><h3>Calibration hors échantillon</h3><p>Split chronologique : 80% des premiers signaux les plus anciens pour l’entraînement, 20% les plus récents pour la validation. Un seul signal par token.</p><p>Tokens uniques évalués : <b>'+(oos.uniqueResolvedTokens||0)+'</b> · entraînement : <b>'+(oos.training?.tokens||0)+'</b> · validation : <b>'+(oos.validation?.tokens||0)+'</b></p><p>Seuil sélectionné sur entraînement : <b>'+(oos.selectedThreshold==null?'Pas encore déterminé':oos.selectedThreshold+'/100')+'</b></p><p>Validation au seuil retenu : <b>'+(oos.holdoutAtSelectedThreshold?.tokens||0)+'</b> tokens · '+(oos.holdoutAtSelectedThreshold?.positive15Pct==null?'résultat indisponible':oos.holdoutAtSelectedThreshold.positive15Pct+'% à +15% · '+oos.holdoutAtSelectedThreshold.averageReturnPct+'% moyen · '+oos.holdoutAtSelectedThreshold.loss20Pct+'% à -20% ou moins')+'</p><p>Comparaison validation : seuil vs tous les tokens <b>'+(oos.baselineComparison?.thresholdVsAllValidation==null?'—':oos.baselineComparison.thresholdVsAllValidation+' points de rendement')+'</b> · seuil vs sélection aléatoire de même taille <b>'+(oos.baselineComparison?.thresholdVsRandomBaseline==null?'—':oos.baselineComparison.thresholdVsRandomBaseline+' points')+'</b></p><small>'+esc(oos.status||'insufficient_sample')+' · '+esc(oos.split||oos.limitations||'Pas encore assez de données indépendantes.')+'</small></article><article class="panel detail-card"><h3>Cohorte prospective : tous les tokens observés</h3><p>Tokens observés : <b>'+(lc.universe?.observed||0)+'</b> · marché trouvé : <b>'+(lc.universe?.marketFound||0)+'</b> · aucun marché après 30 min : <b>'+(lc.universe?.noMarketAfter30m||0)+'</b> · marché tardif : <b>'+(lc.universe?.lateMarket||0)+'</b></p><p>Résultats 1h : <b>'+(lc.universe?.resolved1h||0)+'</b> résolus · '+(lc.universe?.positive15Pct==null?'taux +15% en attente':lc.universe.positive15Pct+'% à +15% · '+lc.universe.average1hPct+'% moyen · '+lc.universe.loss20Pct+'% à -20% ou moins')+'</p>'+Object.entries(lc.bySource||{}).map(([name,v])=>'<p class="factor-row">'+esc(name)+' · '+v.observed+' observés · '+v.noMarketAfter30m+' sans marché après 30 min · '+v.resolved1h+' résolus à 1h</p>').join('')+'<small>'+esc(lc.method||'La cohorte se constitue au fil des nouveaux lancements et pools observés.')+'</small></article>'+'<div class="section-heading spaced"><div><h2>Test sur des tokens historiques</h2><p class="muted">Comparer le comportement du scanner à des données passées.</p></div><button class="secondary" data-go="historical">Ouvrir le test historique →</button></div>';
}
function renderWalletGraph(){
 const g=state.walletGraph||{},s=g.summary||{},clusters=g.clusters||[],edges=g.edges||[];
 view.innerHTML='<div class="section-heading"><div><h2>Graphe des wallets</h2><p class="muted">Relations observées entre wallets suivis, financeurs communs et comportements d’achat rapprochés.</p></div></div>'
 +'<div class="stat-grid">'+[['Wallets suivis',s.trackedWallets||0],['Liens candidats',s.candidateLinks||0],['Liens de financement',s.strongFundingLinks||0],['Indices temporels faibles',s.weakTemporalLinks||0],['Groupes bundle-like',s.bundleLikeCandidates||0],['Groupes récurrents',s.recurrentWalletGroups||0]].map(x=>'<article class="panel stat"><span>'+x[0]+'</span><strong>'+x[1]+'</strong></article>').join('')+'</div>'
 +(clusters.length?'<div class="panel detail-card"><h3>Groupes à examiner</h3>'+clusters.map(c=>'<article class="factor-row"><b>'+c.walletCount+' wallets · '+esc(c.confidence)+'</b><p>'+c.members.map(m=>esc(short(m.address))+' ('+esc((m.roles||[]).join(', '))+')').join(' · ')+'</p><small>'+c.strongFundingLinks+' liens de financement · '+c.repeatedBehaviorLinks+' liens comportementaux</small><p class="footnote">'+esc(c.warning)+'</p></article>').join('')+'</div>':'<div class="panel detail-card"><h3>Aucun groupe suffisamment étayé</h3><p>Le graphe attend davantage de transactions ou de preuves de financement.</p></div>')
 +((g.bundleCandidates||[]).length?'<div class="panel detail-card"><h3>Groupes d’achats synchronisés candidats</h3>'+g.bundleCandidates.slice(0,30).map(x=>'<article class="factor-row"><b>'+esc(x.symbol)+' · '+x.uniqueBuyers+' wallets · '+esc(x.kind)+'</b><p>'+x.wallets.map(short).map(esc).join(' · ')+'</p><small>'+x.confirmedRpcBuyers+' acheteurs RPC confirmés · '+x.geckoSampleBuyers+' échantillons GeckoTerminal · '+x.timeSpanMs+' ms · '+esc(x.evidence)+'</small><p class="footnote">'+esc(x.warning)+'</p></article>').join('')+'</div>':'<div class="panel detail-card"><h3>Aucun groupe d’achats synchronisés candidat</h3><p>Il faut au moins trois wallets distincts observés dans le même slot ou dans une fenêtre de cinq secondes.</p></div>')
 +((g.recurrentWalletGroups||[]).length?'<div class="panel detail-card"><h3>Groupes récurrents sur plusieurs tokens</h3>'+g.recurrentWalletGroups.slice(0,20).map(x=>'<p><b>'+x.sharedWalletCount+' wallets communs</b> · '+x.symbols.map(esc).join(' / ')+'<small>'+x.sharedWallets.map(short).map(esc).join(' · ')+'</small><small class="footnote">'+esc(x.warning)+'</small></p>').join('')+'</div>':'')
 +'<p class="footnote">'+esc(g.bundleLimitations||'Les groupes synchronisés sont des heuristiques et ne prouvent pas une coordination.')+'</p>'
 +'<div class="panel detail-card"><h3>Liens individuels</h3>'+(edges.length?edges.slice(0,100).map(e=>'<p class="factor-row"><b>'+esc(short(e.from))+' &harr; '+esc(short(e.to))+'</b> · '+e.score+'/100 · '+esc(e.classification)+'<small>'+e.sameSlotEvents+' mêmes slots · '+e.closeBuyWindows+' achats rapprochés · '+e.distinctMints+' tokens</small></p>').join(''):'<p>Aucun lien observé.</p>')+'</div>'
 +'<p class="footnote">'+esc(g.limitations||'Ces relations ne prouvent pas une propriété commune ou une coordination.')+'</p>';
}
function renderQuality(){
 const q=state.dataQuality||{},s=q.summary||{},items=q.tokens||[];
 const pct=v=>v==null?'—':v+'%';
 view.innerHTML='<div class="section-heading"><div><h2>Qualité des données</h2><p class="muted">Sépare la quantité d’informations disponibles de leur fraîcheur. Une donnée absente reste inconnue.</p></div></div>'
 +'<div class="stat-grid">'+[['Tokens suivis',s.tokens||0],['Données complètes',pct(s.averageCompletenessPct)],['Fraîcheur moyenne',pct(s.averageFreshnessPct)],['Fraîcheur mesurée',pct(s.freshnessCoveragePct)],['Qualité élevée',s.high||0]].map(x=>'<article class="panel stat"><span>'+x[0]+'</span><strong>'+x[1]+'</strong></article>').join('')+'</div>'
 +'<div class="panel detail-card"><h3>Répartition</h3><p>'+pill('Élevée : '+(s.high||0),'good')+' '+pill('Moyenne : '+(s.medium||0),'warn')+' '+pill('Faible : '+(s.low||0),'bad')+'</p><small>'+esc(q.method||'La complétude n’est pas une probabilité de réussite.')+'</small></div>'
 +(items.length?'<div class="table-wrap"><table><thead><tr><th>Token</th><th>Complétude</th><th>Fraîcheur</th><th>Snapshots</th><th>Alertes de données</th></tr></thead><tbody>'+items.map(t=>'<tr><td><b>'+esc(t.name)+'</b><small class="subtle">$'+esc(t.symbol)+' · '+esc(short(t.mint))+'</small></td><td>'+pct(t.completenessPct)+'</td><td>'+pct(t.freshnessPct)+'</td><td>'+t.sampleCounts.marketSnapshots+'</td><td>'+pill(t.quality,t.quality==='high'?'good':t.quality==='medium'?'warn':'bad')+'<small class="subtle">'+(t.issues||[]).slice(0,3).map(x=>esc(x.message)).join(' · ')+'</small></td></tr>').join('')+'</tbody></table></div>':'<p class="muted">Aucun token à analyser.</p>');
}
function renderWalletIntel(){
 const clusters=state.walletClusters||[];
 view.innerHTML='<h2>Wallet intelligence</h2><p class="muted">Historique des wallets surveillés et comportement des tokens après leurs achats observés.</p>'
 +(clusters.length?'<div class="panel detail-card"><h3>Achats rapprochés / groupes de wallets observés</h3>'+clusters.map(c=>'<p>'+esc(short(c.mint))+' · '+c.trackedWallets+' wallets · '+date(c.at)+'</p><small>'+esc(c.warning)+'</small>').join('')+'</div>':'')
 +(state.walletIntel.length?state.walletIntel.map(w=>'<article class="panel detail-card" style="margin:10px 0"><b>'+esc(w.label)+'</b><p class="mono">'+esc(w.address)+'</p><p>'+w.eventCount+' mouvements · '+w.tokenCount+' tokens · '+date(w.lastActivityAt)+'</p><p>Indice historique du wallet : <b>'+(w.performance.observedPerformanceScore==null?'En attente':w.performance.observedPerformanceScore+'/100')+'</b> · tokens évalués : '+w.performance.matchedTokens+' · médiane 1h : '+(w.performance.median1hReturnPct==null?'—':w.performance.median1hReturnPct+'%')+'</p><p>Achats évalués (un par token) : '+w.performance.matchedBuys+' / '+(w.performance.observedBuyEvents||0)+' événements d’achat · rendement moyen 1h : '+(w.performance.average1hReturnPct==null?'—':w.performance.average1hReturnPct+'%')+' · tokens à +15% : '+(w.performance.winRatePct==null?'—':w.performance.winRatePct+'%')+' · tokens à -20% ou moins : '+(w.performance.severeLossRatePct==null?'—':w.performance.severeLossRatePct+'%')+'</p><small>'+esc(w.performance.confidence)+' · '+esc(w.performance.method)+'</small>'+(w.error?'<p>'+esc(w.error)+'</p>':'')+w.tokens.map(t=>'<p>'+esc(t.name)+' ($'+esc(t.symbol)+') · '+t.buys+' entrées / '+t.sells+' sorties</p>').join('')+'</article>').join(''):'<p class="muted">Ajoute un wallet dans Smart Money pour commencer la collecte.</p>')
 +'<p class="footnote">Ce score observe les rendements des tokens après des achats détectés. Ce n’est pas le PnL réel du wallet : prix exact au bloc, frais et slippage ne sont pas mesurés. Les achats groupés ne prouvent pas que les wallets sont liés.</p>';
}
function renderAlerts(){
 const labels={danger:'Danger',opportunity:'Opportunité',watch:'À surveiller'};
 const colors={danger:'bad',opportunity:'good',watch:'warn'};
 view.innerHTML='<div class="section-heading"><h2>Alertes & historique</h2></div>'
 +(state.alerts.length?state.alerts.map(a=>'<article class="panel alert-row"><div>'+pill(labels[a.level]||'Signal',colors[a.level]||'neutral')+' <b>'+esc(a.symbol)+'</b><p>'+esc(a.message)+'</p><small>'+date(a.at)+' · couverture '+a.coverage+'%</small>'+(a.reasons?.length?'<p class="footnote">'+a.reasons.map(esc).join(' · ')+'</p>':'')+'</div><button class="mini-btn" data-token="'+esc(a.mint)+'">Détails</button></article>').join(''):'<p class="muted">Aucune alerte pour le moment.</p>');
}
function renderHistorical(){const h=state.historical||{coins:[],completed:0,total:32},cohorts=h.cohortSummary||{},signalCohorts=h.signalPerformanceByCohort||{},cases=h.caseStudies||[];const caseHtml=cases.length?'<div class="section-heading spaced"><div><h2>Cas documentés de pertes et sorties coordonnées</h2><p class="muted">Études de cas sourcées, séparées du replay quantitatif faute de séries OHLCV et de mint historique vérifiés.</p></div></div><div class="two-col">'+cases.map(x=>'<article class="panel detail-card"><b>'+esc(x.name)+' · '+esc(x.symbol)+'</b>'+(x.mint?'<p class="mono">'+esc(x.mint)+'</p>':'')+(x.quantitativeReplay?'<p><b>Inclus dans le replay OHLCV</b></p>':'<p class="muted">Étude qualitative uniquement</p>')+'<p>'+esc(x.incidentDate)+' · '+esc(x.classification)+' · '+esc(x.collapseWindow)+'</p>'+(x.reportedDrawdownPct==null?'':'<p>Baisse rapportée : <b>'+x.reportedDrawdownPct+'%</b></p>')+(x.reportedMarketCapBeforeUsd==null?'':'<p>Capitalisation rapportée : '+usd(x.reportedMarketCapBeforeUsd)+' → '+usd(x.reportedMarketCapAfterUsd)+'</p>')+'<p>'+esc(x.reportedWalletPattern)+'</p><small>'+esc(x.identityNote)+'</small><p><a class="external-link" href="'+esc(x.evidenceUrl)+'" target="_blank" rel="noopener">Source de l’étude</a>'+(x.mintSourceUrl?' · <a class="external-link" href="'+esc(x.mintSourceUrl)+'" target="_blank" rel="noopener">Source du mint</a>':'')+'</p></article>').join('')+'</div>':'',signalPerformance=(h.coins||[]).filter(x=>x.completed&&x.historicalSignalPerformance);const signalCohortHtml=Object.entries(signalCohorts).length?'<div class="section-heading spaced"><div><h2>Qualité des alertes par cohorte</h2><p class="muted">Chaque token pèse autant dans la moyenne, quel que soit le nombre de bougies. Les horizons quotidiens se chevauchent.</p></div></div><div class="two-col">'+Object.entries(signalCohorts).map(([name,cohort])=>'<article class="panel detail-card"><b>'+esc(name)+'</b>'+Object.entries(cohort.byHorizon||{}).map(([horizon,v])=>'<p><b>'+horizon+'</b> · '+v.alerts.tokens+' tokens · '+v.alerts.signals+' alertes · '+(v.alerts.averageTokenReturnPct==null?'—':v.alerts.averageTokenReturnPct+'% rendement moyen/token')+' · '+(v.alerts.averageTokenPositive15Pct==null?'—':v.alerts.averageTokenPositive15Pct+'% tokens à +15%')+' · '+(v.alerts.averageTokenLoss20Pct==null?'—':v.alerts.averageTokenLoss20Pct+'% tokens à -20%')+' · '+(v.averagePerTokenAlertLiftPct==null?'—':v.averagePerTokenAlertLiftPct+' pts vs tous les signaux')+'</p>').join('')+'</article>').join('')+'</div>':'<p class="muted">Les performances par cohorte apparaîtront après collecte de séries historiques suffisantes.</p>';view.innerHTML='<div class="section-heading"><div><h2>Test sur des tokens historiques</h2><p class="muted">Cohortes gagnants, survivants et tokens boom-bust; mesure des rendements et drawdowns.</p></div><button class="secondary" data-go="backtest">Retour aux résultats</button></div><div class="panel detail-card"><p><b>'+h.completed+'/'+h.total+'</b> tokens historiques analysés</p><p class="footnote">Performance des alertes par rapport à l&#39;ensemble des signaux sur des horizons fixes après chaque signal (proxy journalier).</p><div class="two-col">'+signalPerformance.map(x=>'<article class="panel detail-card"><b>'+esc(x.symbol)+'</b>'+Object.entries(x.historicalSignalPerformance).map(([horizon,v])=>'<p>'+horizon+' · '+v.alerts.signals+' alertes évaluées · '+(v.alerts.averageReturnPct==null?'—':v.alerts.averageReturnPct+'% moyen')+' · '+(v.alerts.positive15Pct==null?'—':v.alerts.positive15Pct+'% à +15%')+' · '+(v.alertVsAllAveragePct==null?'—':v.alertVsAllAveragePct+' pts vs tous les signaux')+'</p>').join('')+'</article>').join('')+'</div><div class="two-col">'+Object.entries(cohorts).map(([name,v])=>'<article class="panel detail-card"><b>'+esc(name)+'</b><p>'+v.tokens+' tokens · '+v.signals+' signaux · '+v.alerts+' alertes</p><p>Rendement final médian : '+(v.medianTerminalReturnPct==null?'—':v.medianTerminalReturnPct+'%')+' · moyen : '+(v.averageTerminalReturnPct==null?'—':v.averageTerminalReturnPct+'%')+'</p><p>Drawdown maximal moyen : '+(v.averageMaxDrawdownPct==null?'—':v.averageMaxDrawdownPct+'%')+'</p></article>').join('')+'</div>'+signalCohortHtml+'<div class="table-wrap"><table><thead><tr><th>Token / cohorte</th><th>Signaux</th><th>Alertes</th><th>1er signal</th><th>Hausse après signal</th><th>Rendement fenêtre</th><th>Max drawdown</th><th>État</th></tr></thead><tbody>'+h.coins.map(c=>'<tr><td><b>'+esc(c.symbol)+'</b><small class="subtle">'+esc(c.cohort||'—')+' · '+esc(c.name)+'</small></td><td>'+(c.completed?c.signalCount:'—')+'</td><td>'+(c.completed?c.alertCount:'En attente')+'</td><td>'+(c.completed&&c.firstAlert?date(c.firstAlert.at):'—')+'</td><td>'+(c.completed&&c.firstAlert?c.firstAlert.forwardMaxUpsidePct+'%':'—')+'</td><td>'+(c.completed&&c.terminalReturnPct!=null?c.terminalReturnPct+'%':'—')+'</td><td>'+(c.completed&&c.maxDrawdownPct!=null?c.maxDrawdownPct+'%':'—')+'</td><td>'+(c.error?esc(c.error):c.completed?'Terminé':'À analyser')+'</td></tr>').join('')+'</tbody></table></div>'+caseHtml+'<p class="footnote">'+esc(h.limitations||'Données historiques collectées progressivement.')+'</p><p class="footnote">Le replay est quotidien et ne reconstitue pas les signaux intrajournaliers, les holders ou les données exactes au lancement. Les résultats historiques ne garantissent pas le comportement futur.</p></div>';}
