 const trades=(data.recentTrades||[]).slice(0,20).map(t=>'<p class="factor-row">'+pill(t.action==='buy'?'ACHAT':'VENTE',t.action==='buy'?'good':'warn')+' '+esc(short(t.wallet))+' · '+esc(short(t.mint))+' · '+(t.quoteAmount==null?'montant inconnu':Number(t.quoteAmount).toFixed(4)+' '+esc(t.quoteAsset||''))+' · '+(t.confirmed?'swap confirmé':'flux non confirmé')+' · '+date(t.at)+'</p>').join('');
 const backtest=state.walletSignalBacktest||{},horizons=backtest.byHorizon||{};
